/*
 * High-performance portfolio calculations using C extension
 *
 * Implements:
 *   risk   = sqrt(x^T * S * x)
 *   return = x^T * r
 *
 * NumPy C API is used for zero-copy access to contiguous float64 arrays.
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_arg, *cov_arg;
    PyArrayObject *weights = NULL, *cov = NULL;

    /* Parse NumPy arrays */
    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_arg,
                                       &PyArray_Type, &cov_arg))
        return NULL;

    /* Ensure float64, C-contiguous, aligned, native-byte-order arrays. */
    weights = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)weights_arg, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (weights == NULL)
        return NULL;

    cov = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)cov_arg, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (cov == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    if (PyArray_NDIM(weights) != 1 || PyArray_NDIM(cov) != 2) {
        PyErr_SetString(PyExc_ValueError,
                        "weights must be 1-D and covariance matrix must be 2-D");
        goto error;
    }

    npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(cov, 0) != n || PyArray_DIM(cov, 1) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "covariance matrix dimensions must match weights");
        goto error;
    }

    const double *x = (const double *)PyArray_DATA(weights);
    const double *S = (const double *)PyArray_DATA(cov);
    const npy_intp nn = n;  /* keep index type consistent */

    /* Step 1: temp = S * x, row by row (same accumulation order as baseline). */
    double *temp = (double *)malloc((size_t)n * sizeof(double));
    if (temp == NULL) {
        PyErr_NoMemory();
        goto error;
    }

    for (npy_intp i = 0; i < nn; ++i) {
        const double *row = S + i * nn;
        double row_sum = 0.0;
        for (npy_intp j = 0; j < nn; ++j)
            row_sum += row[j] * x[j];
        temp[i] = row_sum;
    }

    /* Step 2: risk_squared = x^T * temp. */
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < nn; ++i)
        risk_squared += x[i] * temp[i];

    free(temp);

    Py_DECREF(weights);
    Py_DECREF(cov);

    if (risk_squared < 0.0) {
        if (risk_squared > -1e-15)
            risk_squared = 0.0;  /* guard against tiny negative round-off */
        else {
            PyErr_SetString(PyExc_ValueError,
                            "computed portfolio variance is negative");
            return NULL;
        }
    }

    return PyFloat_FromDouble(sqrt(risk_squared));

error:
    Py_XDECREF(weights);
    Py_XDECREF(cov);
    return NULL;
}

static PyObject* portfolio_return_c(PyObject *self, PyObject *args) {
    PyArrayObject *weights_arg, *returns_arg;
    PyArrayObject *weights = NULL, *returns = NULL;

    if (!PyArg_ParseTuple(args, "O!O!", &PyArray_Type, &weights_arg,
                                       &PyArray_Type, &returns_arg))
        return NULL;

    weights = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)weights_arg, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (weights == NULL)
        return NULL;

    returns = (PyArrayObject *)PyArray_FROM_OTF(
        (PyObject *)returns_arg, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (returns == NULL) {
        Py_DECREF(weights);
        return NULL;
    }

    if (PyArray_NDIM(weights) != 1 || PyArray_NDIM(returns) != 1) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected returns must be 1-D");
        goto error;
    }

    npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(returns, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected returns must have equal length");
        goto error;
    }

    const double *x = (const double *)PyArray_DATA(weights);
    const double *r = (const double *)PyArray_DATA(returns);

    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        total_return += x[i] * r[i];

    Py_DECREF(weights);
    Py_DECREF(returns);

    return PyFloat_FromDouble(total_return);

error:
    Py_XDECREF(weights);
    Py_XDECREF(returns);
    return NULL;
}

static PyMethodDef module_methods[] = {
    {"portfolio_risk_c", portfolio_risk_c, METH_VARARGS, "Calculate portfolio risk"},
    {"portfolio_return_c", portfolio_return_c, METH_VARARGS, "Calculate portfolio return"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized_c",
    "Optimized portfolio calculations",
    -1,
    module_methods
};

PyMODINIT_FUNC PyInit_portfolio_optimized_c(void) {
    import_array();  /* Initialize NumPy C API */
    return PyModule_Create(&moduledef);
}

/*
 * High-performance portfolio calculations using C extension
 *
 * Implements:
 *   risk   = sqrt(x^T * S * x)
 *   return = x^T * r
 *
 * Two fast paths are provided:
 *   - Python list/tuple inputs are read directly in C (avoids the expensive
 *     nested-list -> ndarray conversion for large portfolios).
 *   - NumPy arrays are accessed through the NumPy C API (zero-copy when they
 *     are already contiguous float64 arrays).
 *
 * Accumulation order matches the pure-Python baseline so results agree to
 * within floating-point round-off (well below 1e-10).
 */

#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>
#include <stdlib.h>

/* Convert a Python number to double, using the fast macro for exact floats. */
static inline int item_as_double(PyObject *obj, double *out) {
    if (PyFloat_CheckExact(obj)) {
        *out = PyFloat_AS_DOUBLE(obj);
        return 0;
    }
    *out = PyFloat_AsDouble(obj);
    return (*out == -1.0 && PyErr_Occurred()) ? -1 : 0;
}

static inline int is_sequence_container(PyObject *obj) {
    return PyList_Check(obj) || PyTuple_Check(obj);
}

/*
 * Compute sqrt(x^T * S * x) directly from list/tuple inputs.
 * Returns 1 on success, 0 if the inputs are not suitable for this fast path,
 * -1 on error (Python exception set).
 */
static int risk_from_sequences(PyObject *weights_obj, PyObject *cov_obj,
                               double *result) {
    if (!is_sequence_container(weights_obj) ||
        !is_sequence_container(cov_obj))
        return 0;

    PyObject *wseq = NULL, *cseq = NULL;
    double *x = NULL, *temp = NULL;
    int status = 0;

    wseq = PySequence_Fast(weights_obj, "weights must be a sequence");
    if (wseq == NULL)
        return -1;
    cseq = PySequence_Fast(cov_obj, "covariance matrix must be a sequence");
    if (cseq == NULL) {
        Py_DECREF(wseq);
        return -1;
    }

    npy_intp n = (npy_intp)PySequence_Fast_GET_SIZE(wseq);
    if ((npy_intp)PySequence_Fast_GET_SIZE(cseq) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "covariance matrix dimensions must match weights");
        status = -1;
        goto done;
    }

    x = (double *)malloc((size_t)n * sizeof(double));
    temp = (double *)malloc((size_t)n * sizeof(double));
    if (x == NULL || temp == NULL) {
        PyErr_NoMemory();
        status = -1;
        goto done;
    }

    /* Convert weights once instead of re-reading them in the inner loop. */
    PyObject **witems = PySequence_Fast_ITEMS(wseq);
    for (npy_intp i = 0; i < n; ++i) {
        if (item_as_double(witems[i], &x[i]) < 0) {
            status = -1;
            goto done;
        }
    }

    /* Step 1: temp = S * x (same row-major accumulation as baseline). */
    PyObject **citems = PySequence_Fast_ITEMS(cseq);
    for (npy_intp i = 0; i < n; ++i) {
        PyObject *row_obj = citems[i];
        if (!is_sequence_container(row_obj)) {
            status = 0;  /* fall back to NumPy conversion path */
            goto done;
        }

        PyObject *row = PySequence_Fast(row_obj, "covariance row must be a sequence");
        if (row == NULL) {
            status = -1;
            goto done;
        }
        if ((npy_intp)PySequence_Fast_GET_SIZE(row) != n) {
            Py_DECREF(row);
            PyErr_SetString(PyExc_ValueError,
                            "covariance matrix must be square and match weights");
            status = -1;
            goto done;
        }

        PyObject **ritems = PySequence_Fast_ITEMS(row);
        double row_sum = 0.0;
        for (npy_intp j = 0; j < n; ++j) {
            double s;
            if (item_as_double(ritems[j], &s) < 0) {
                Py_DECREF(row);
                status = -1;
                goto done;
            }
            row_sum += s * x[j];
        }
        Py_DECREF(row);
        temp[i] = row_sum;
    }

    /* Step 2: risk_squared = x^T * temp. */
    double risk_squared = 0.0;
    for (npy_intp i = 0; i < n; ++i)
        risk_squared += x[i] * temp[i];

    if (risk_squared < 0.0) {
        if (risk_squared > -1e-15)
            risk_squared = 0.0;  /* guard against tiny negative round-off */
        else {
            PyErr_SetString(PyExc_ValueError,
                            "computed portfolio variance is negative");
            status = -1;
            goto done;
        }
    }

    *result = sqrt(risk_squared);
    status = 1;

done:
    free(x);
    free(temp);
    Py_XDECREF(wseq);
    Py_XDECREF(cseq);
    return status;
}

/* Compute x^T * r directly from list/tuple inputs. */
static int return_from_sequences(PyObject *weights_obj, PyObject *returns_obj,
                                 double *result) {
    if (!is_sequence_container(weights_obj) ||
        !is_sequence_container(returns_obj))
        return 0;

    PyObject *wseq = NULL, *rseq = NULL;
    int status = 0;

    wseq = PySequence_Fast(weights_obj, "weights must be a sequence");
    if (wseq == NULL)
        return -1;
    rseq = PySequence_Fast(returns_obj, "expected returns must be a sequence");
    if (rseq == NULL) {
        Py_DECREF(wseq);
        return -1;
    }

    npy_intp n = (npy_intp)PySequence_Fast_GET_SIZE(wseq);
    if ((npy_intp)PySequence_Fast_GET_SIZE(rseq) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected returns must have equal length");
        status = -1;
        goto done;
    }

    PyObject **witems = PySequence_Fast_ITEMS(wseq);
    PyObject **ritems = PySequence_Fast_ITEMS(rseq);
    double total_return = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        double w, r;
        if (item_as_double(witems[i], &w) < 0 ||
            item_as_double(ritems[i], &r) < 0) {
            status = -1;
            goto done;
        }
        total_return += w * r;
    }

    *result = total_return;
    status = 1;

done:
    Py_XDECREF(wseq);
    Py_XDECREF(rseq);
    return status;
}

/* NumPy fallback: sqrt(x^T * S * x). */
