            goto done;
        }
    }

    *result = sqrt(risk_squared);
    status = 1;

done:
    free(temp);
    Py_XDECREF(weights);
    Py_XDECREF(cov);
    return status;
}

/* NumPy fallback: x^T * r. */
static int return_from_arrays(PyObject *weights_obj, PyObject *returns_obj,
                              double *result) {
    PyArrayObject *weights = NULL, *returns = NULL;
    int status = -1;

    weights = (PyArrayObject *)PyArray_FROM_OTF(
        weights_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (weights == NULL)
        return -1;

    returns = (PyArrayObject *)PyArray_FROM_OTF(
        returns_obj, NPY_DOUBLE, NPY_ARRAY_IN_ARRAY);
    if (returns == NULL)
        goto done;

    if (PyArray_NDIM(weights) != 1 || PyArray_NDIM(returns) != 1) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected returns must be 1-D");
        goto done;
    }

    npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(returns, 0) != n) {
        PyErr_SetString(PyExc_ValueError,
                        "weights and expected returns must have equal length");
        goto done;
    }

    const double *x = (const double *)PyArray_DATA(weights);
    const double *r = (const double *)PyArray_DATA(returns);

    double total_return = 0.0;
