static PyObject* portfolio_risk_c(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;
    double result = 0.0;

    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    int status = risk_from_sequences(weights_obj, cov_obj, &result);
    if (status < 0)
        return NULL;
    if (status == 0) {
        if (risk_from_arrays(weights_obj, cov_obj, &result) < 0)
            return NULL;
    }

    return PyFloat_FromDouble(result);
